export default function MenuCard({ item, addToCart }) {
  const outOfStock = item.stock <= 0;

  return (
    <div className={`menu-card ${outOfStock ? "out-stock" : ""}`}>
      <h3>{item.name}</h3>
      <p>₹{item.price}</p>

      <p className={`stock ${outOfStock ? "danger" : "ok"}`}>
        {outOfStock ? "Out of Stock" : `Stock: ${item.stock}`}
      </p>

      <button
        onClick={() => addToCart(item)}
        disabled={outOfStock}
        className="btn btn-success"
      >
        {outOfStock ? "Unavailable" : "Add to Cart"}
      </button>
    </div>
  );
}
